WITH matched_keys AS (SELECT product_id FROM order_items INTERSECT SELECT product_id FROM order_items WHERE product_id IS NULL), kept_rows AS (SELECT s.* FROM order_items s INNER JOIN matched_keys k ON s.product_id = k.product_id), with_dims AS (SELECT e.*, o.discount FROM kept_rows e LEFT JOIN orders o ON e.order_id = o.id), valid AS (SELECT *, ROUND(discount * 100, 2) AS discount_scaled FROM with_dims WHERE product_id IS NOT NULL AND quantity >= 8), report AS (SELECT id, order_id, product_id, quantity, discount, discount_scaled FROM valid) SELECT id, order_id, quantity, discount FROM report ORDER BY quantity;
